"""Seven coordinated October20 changes, using disposable offline browser profiles."""
import base64,json,sys,time
def run(c,root,name):
 out=root/'tests/economy-update-evidence';out.mkdir(exist_ok=True);c.sock.settimeout(300)
 entry=root/('DIST/index.html' if '--dist' in sys.argv else 'index.html');c.navigate(entry,timeout=60)
 for _ in range(400):
  if c.evaluate('!!window.AL?.game&&!!AL.EconomyUI'):break
  time.sleep(.05)
 else:raise RuntimeError('Economy update did not boot')
 c.evaluate('AL.Startup.finish();AL.Save.unlock();AL.UI.close();AL.Store.close();AL.Shell.close();AL.game.settings.speed=0')
 result=c.evaluate((root/'tests/economy_update_checks.js').read_text(encoding='utf8'));checks=result['checks'];print(json.dumps({'stage':'model','passed':result['passed'],'failed':result['failed'],'failures':[r for r in checks if not r['pass']]}),flush=True)
 def js(s):return c.evaluate('(()=>{'+s+'})()')
 def ck(name,expr):
  try:checks.append({'name':name,'pass':bool(c.evaluate('!!('+expr+')'))})
  except Exception as e:checks.append({'name':name,'pass':False,'error':str(e)})
 js("AL.game=economyFixture();AL.UI.render();AL.CasinoUI.open();document.querySelector('[data-casino=profile]').click()")
 ck('Casino Profile owns the only spending-limit editor and visit history',"document.querySelectorAll('#casino-limit').length===1&&document.querySelector('#casino-dialog [data-casino=profile][aria-pressed=true]')&&document.querySelector('#casino-dialog').textContent.includes('Recent Casino Visits')")
 js("document.querySelector('#casino-limit input').value='80';document.querySelector('#casino-limit').requestSubmit()")
 ck('Actual Profile limit form saves the existing authoritative limit',"AL.game.casino.dailyLimit===80")
 js("document.querySelector('[data-casino=gold]').click()")
 ck('Gold Fish table labels PAIR2x and no longer duplicates Profile controls',"document.querySelector('#casino-dialog').textContent.includes('PAIR — 2×')&&!document.querySelector('#casino-limit')")
 js("AL.CasinoUI.close();AL.Shell.open('journal','achievements')")
 ck('Existing achievement tab contains automatic profile milestones',"document.querySelector('#primary-content').textContent.includes('First-time milestones')")
 js("AL.Shell.open('journal','quests')")
 ck('Existing objectives tab shows optional care progress without unspecified cash rewards',"document.querySelectorAll('#primary-content progress').length===13&&document.querySelector('#primary-content').textContent.includes('no additional AC or XP')")
 js("AL.Shell.close();const e=AL.game.tanks[0].equipment.find(e=>e.type==='filter');e.reliability.parts.impeller=45;e.reliability.maintenance=50;window.partEquipment=e.id;AL.InventoryUI.inspect({id:e.id})")
 ck('Inspector separates Maintenance from Replace Part',"document.querySelector('#dialog-body [data-action=service]')&&document.querySelector('#dialog-body [data-economy=parts]')")
 js("document.querySelector('#dialog-body [data-economy=parts]').click()")
 ck('Part dialog shows matching rating, new-part price and owned option',"document.querySelector('#dialog-body').textContent.includes('new-part price')&&document.querySelectorAll('#dialog-body [data-economy=replace]').length===2")
 js("document.querySelector('#dialog-body [data-economy=replace]').click()")
 ck('Actual Replace Part purchase writes component and factual history once',"AL.game.tanks[0].equipment.find(e=>e.id===partEquipment).reliability.parts.impeller>99.99&&AL.game.equipmentReliability.events.at(-1).kind==='part-replacement'")
 js("AL.UI.close();AL.Store.open('sell','saltwater')")
 ck('Store Sell lists owned aquariums and Review button',"document.querySelector('#store-products').textContent.includes('Sell Entire Aquarium')&&!!document.querySelector('[data-economy=sale]')")
 js("document.querySelector('[data-economy=sale]').click()")
 ck('Whole sale requires separate explicit checkbox confirmation and itemized exact total',"!!document.querySelector('[data-form=wholeAquariumSale] input[required]')&&document.querySelector('#dialog-body').textContent.includes('This action cannot be undone.')&&document.querySelectorAll('.sale-rows p').length>=5")
 js("document.querySelector('[data-form=wholeAquariumSale] input').checked=true;document.querySelector('[data-form=wholeAquariumSale]').requestSubmit()")
 ck('Last-tank sale shows actual empty state and saves it',"AL.game.tanks.length===0&&AL.game.selectedTank===''&&document.querySelector('#tank-name').textContent==='No aquarium owned'&&AL.Save.parse(JSON.stringify(AL.game)).tanks.length===0")
 for window,tab in [('aquariums','new'),('journal','history'),('equipment','inventory'),('journal','achievements'),('journal','quests'),('settings','preferences')]:
  js(f"AL.Store.close();AL.Shell.open('{window}','{tab}')")
  ck(f'Empty ownership: {window}/{tab} remains usable',"document.querySelector('#primary-content').textContent.length>0")
 js("AL.Shell.close();AL.Store.open('tanks','saltwater')")
 ck('New aquarium can still be configured after selling the last tank',"document.querySelector('#dialog-body').textContent.includes('Choose an aquarium')")
 js("AL.UI.close();AL.Store.close();let s;for(let i=0;i<1000;i++){s=economyFixture(i);const p={id:'daily:0:0',species:'clown',args:{dailySlot:'daily:0:0'}};if(AL.PairOffers.roll(s.accountId+':'+AL.PairOffers.identity(s,p))<500)break;}s.dailyStore.slots[0]={id:'daily:0:0',species:'clown',variety:null,rarity:AL.Rarity.species('clown').name,remaining:4};AL.game=s;AL.UI.render();AL.Store.open('fish','saltwater');AL.Store.details('daily:0:0');window.savedPair=Object.values(AL.game.pairOffers.offers).find(o=>o.available);window.pairBefore=JSON.stringify(savedPair)")
 ck('Actual store details persists a compatible breeding-pair option',"!!document.querySelector('#purchase-pair')&&savedPair.fish.length===2&&document.querySelector('#dialog-body').textContent.includes('not an established bonded pair')")
 js("AL.UI.close();AL.Store.details('daily:0:0')")
 ck('Close/reopen and local JSON round trip preserve the actual offer and specimens',"JSON.stringify(AL.game.pairOffers.offers[savedPair.id])===pairBefore&&JSON.stringify(AL.Save.parse(JSON.stringify(AL.game)).pairOffers.offers[savedPair.id])===pairBefore")
 js("document.querySelector('#purchase-pair').value='pair';document.querySelector('#purchase-pair').dispatchEvent(new Event('change'));window.pairMoney=AL.game.credits;window.pairIds=savedPair.fish.map(f=>f.id);document.querySelector('[data-form=storePurchase]').requestSubmit()")
 ck('Actual store pair form charges once and transfers both permanent identities',"AL.game.tanks[0].fish.length===2&&pairIds.every(id=>AL.game.tanks[0].fish.some(f=>f.id===id))&&AL.game.credits===pairMoney-360+50&&AL.game.pairOffers.receipts.length===1")
 js("AL.UI.close();AL.Store.close();AL.game=economyFixture();AL.UI.render();AL.Shell.open('equipment','care')")
 for w,h in [(1920,1080),(1600,900),(1366,768),(390,844)]:
  c.call('Emulation.setDeviceMetricsOverride',{'width':w,'height':h,'deviceScaleFactor':1,'mobile':False});js("AL.Shell.close();AL.CasinoUI.open();document.querySelector('[data-casino=profile]').click()")
  ck(f'{w}x{h}: Casino Profile fits horizontally',"document.documentElement.scrollWidth<=innerWidth&&document.querySelector('#casino-dialog').scrollWidth<=document.querySelector('#casino-dialog').clientWidth")
  (out/f'{name}-casino-account-{w}.png').write_bytes(base64.b64decode(c.call('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})['data']))
  js("AL.CasinoUI.close();AL.Store.open('sell','saltwater');document.querySelector('[data-economy=sale]').click()")
  ck(f'{w}x{h}: itemized sale fits horizontally',"document.documentElement.scrollWidth<=innerWidth&&document.querySelector('#dialog-body').scrollWidth<=document.querySelector('#dialog-body').clientWidth")
  (out/f'{name}-sale-{w}.png').write_bytes(base64.b64decode(c.call('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})['data']));js("AL.UI.close();AL.Store.close()")
 js("AL.game=economyFixture();const id=AL.game.selectedTank,q=AL.AquariumSale.quote(AL.game,id);AL.game=AL.Core.act(AL.game,'sellEntireAquarium',{tankId:id,confirmed:true,fingerprint:q.fingerprint});AL.game.update29.tutorial.status='active';AL.game.update29.tutorial.step=0;AL.game.simulationCheckpoint=Date.now();window.zeroSaveResult=AL.UI.save();if(!zeroSaveResult.ok)throw Error('Zero-tank save: '+zeroSaveResult.message);")
 c.navigate(entry,timeout=60)
 for _ in range(400):
  if c.evaluate('!!window.AL?.game&&!!document.querySelector("[data-startup=continue]")'):break
  time.sleep(.05)
 else:
  diagnostic=c.evaluate("({ready:document.readyState,title:document.querySelector('#startup-content')?.textContent,game:!!AL?.game,tanks:AL?.game?.tanks?.length,saveError:AL?.Save?.lastError,pending:AL?.Startup?.pending,rawTanks:(()=>{try{return JSON.parse(localStorage.getItem('aquarium-life-v2')).tanks.length}catch{return null}})()})")
  diagnostic['errors']=[e for e in c.events if e.get('method')=='Runtime.exceptionThrown']
  (out/f'{name}-zero-reload-failure.json').write_text(json.dumps(diagnostic,indent=2),encoding='utf8')
  raise RuntimeError('Saved zero-tank profile did not reach Continue: '+json.dumps(diagnostic))
 ck('Actual page reload restores the sold-last-tank profile without granting a free aquarium',"AL.game.tanks.length===0&&AL.game.selectedTank===''&&AL.game.aquariumSales.receipts.length===1")
 js("document.querySelector('[data-startup=continue]').click()")
 for _ in range(300):
  if c.evaluate('!AL.Startup.pending&&!AL.Offline.busy'):break
  time.sleep(.05)
 ck('Real Continue completes offline catch-up with zero aquariums and keeps an honest empty scene',"!AL.Startup.pending&&!AL.Offline.busy&&AL.game.tanks.length===0&&document.getElementById('tank-name').textContent==='No aquarium owned'")
 js("AL.UI.close();AL.TutorialUI.update();document.querySelector('#tutorial-tooltip [data-guide=skip]').click();document.querySelector('[data-guide-confirm=skip]').click()")
 ck('Account tutorial controls remain usable after selling the last aquarium',"AL.game.update29.tutorial.status==='skipped'&&AL.game.tanks.length===0")
 js("window.emptyXp=AL.game.xp;const old=AL.game.aquariumSales.receipts[0].tankId;AL.game=AL.Core.act(AL.game,'buyTank',{volume:75,water:'marine',kind:'reef'});window.restoredOldTank=AL.game.tanks.some(t=>t.id===old);AL.UI.render();AL.UI.save()")
 ck('A fresh aquarium can be bought after actual reload, without restoring sold IDs or repeating the size award',"AL.game.tanks.length===1&&!restoredOldTank&&AL.game.xp===emptyXp&&AL.Save.validate(AL.game)===AL.game")
 errors=[e for e in c.events if e.get('method')=='Runtime.exceptionThrown'];checks.append({'name':'No uncaught JavaScript errors','pass':not errors,'errors':errors})
 result.update({'entry':entry.relative_to(root).as_posix(),'checks':checks,'passed':sum(x['pass'] for x in checks),'failed':sum(not x['pass'] for x in checks)})
 (out/f'{name}-results.json').write_text(json.dumps(result,indent=2),encoding='utf8');print(json.dumps({'passed':result['passed'],'failed':result['failed'],'failures':[r for r in checks if not r['pass']],'pairSample':result.get('pairSample')},indent=2),flush=True)
 return int(result['failed']>0)
